import { setCanonicalStatus, updateCanonicalStatus } from './canonical-status-fixture.js';
// AI-generated by scale-codex-4. Real disposable Firestore; small budgets exercise production lifecycle semantics.
import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { readCurrentStateRefresh } from '../src/view/current-state-progress-reader.js';
import { currentProjectId, inProject } from '../src/firestore.js';
import { configureCurrentState, currentStateStats, readCurrentState, stopCurrentState } from '../src/view/current-state.js';
import { resetEmulator } from './helpers.js';

const SMALL = 'a'.repeat(64), BIG = 'b'.repeat(64), OTHER = 'c'.repeat(64);
let restore = () => {}, clock = 0;
beforeEach(async () => { stopCurrentState(); await resetEmulator(); clock = 0;
  restore = configureCurrentState({ maxProjects: 1, pageSize: 2, lingerMs: 60_000, clock: () => clock }); });
afterEach(() => { restore(); stopCurrentState(); });
const T = Date.now();
async function agentsIn(projectId: string, n: number) {
  await inProject(projectId, async () => { for (let i = 0; i < n; i++) await setCanonicalStatus(`${projectId.slice(0, 1)}-agent-${i}`,{ runId: null, runEndedAt: null,
    agent: { name: `agent-${i}`, ownerProfileId: 'owner', connectionEpoch: 0, revokedAt: null, focus: null, personaText: '' } } as never); });
}
const read = (projectId: string, cursor?: string, viewer = 'viewer') => inProject(projectId, () => readCurrentState(viewer, false, cursor, T));
async function drain(projectId: string, cursor?: string, viewer = 'viewer') {
  let answer = await read(projectId, cursor, viewer), pages = 1;
  const rows = [...answer.rows];
  while (answer.more) { answer = await read(projectId, answer.cursor, viewer); rows.push(...answer.rows); pages++; }
  return { answer, pages, rows };
}

test('a live overcap CURRENT survives completed polls and shares changes across four viewers without displacing the small project', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 7);
  const small = await drain(SMALL);
  const viewers = ['one', 'two', 'three', 'four'];
  const first = await Promise.all(viewers.map(viewer => drain(BIG, undefined, viewer)));
  expect(first.every(a => a.pages === 4 && a.rows.length === 7)).toBe(true);
  expect(currentStateStats()).toMatchObject({ cachedProjects: 2, primaryProjects: 1, overflowProjects: 1, oneShots: 0, attaches: 2 });
  const before = currentStateStats();
  for (let poll = 0; poll < 3; poll++) for (let n = 0; n < viewers.length; n++) {
    const answer = await read(BIG, first[n]!.answer.cursor, viewers[n]);
    expect(answer).toMatchObject({ complete: true, rows: [] });
  }
  await inProject(BIG, () => updateCanonicalStatus('b-agent-0',{ 'agent.focus': { text: 'fresh current', updatedAt: 1 } }));
  let changed = await read(BIG, first[0]!.answer.cursor, viewers[0]);
  for (let attempt = 0; !changed.rows.length && attempt < 100; attempt++) {
    await new Promise(resolve => setTimeout(resolve, 10)); changed = await read(BIG, first[0]!.answer.cursor, viewers[0]);
  }
  expect(changed.rows.find(r => r.id === 'b-agent-0')).toMatchObject({ focus: { text: 'fresh current' } });
  for (let n = 1; n < viewers.length; n++) expect((await read(BIG, first[n]!.answer.cursor, viewers[n])).rows).toEqual(changed.rows);
  expect(await read(SMALL, small.answer.cursor)).toMatchObject({ complete: true, rows: [] });
  const after = currentStateStats();
  expect(after.oneShots).toBe(0); expect(after.attaches).toBe(before.attaches);
  expect(after.rowDocs - before.rowDocs).toBe(1);
  expect(after.currentBytes).toBeLessThanOrEqual(32 * 1024 * 1024);
});

test('idle-only overflow eviction preserves the cursor floor and the primary project; recovery never restarts page one', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 7); await agentsIn(OTHER, 7);
  await drain(SMALL);
  const first = await read(BIG);
  const budget = currentStateStats().currentBytes;
  configureCurrentState({ currentBytes: budget });
  await drain(OTHER);
  expect(currentStateStats()).toMatchObject({ primaryProjects: 1, overflowProjects: 1, currentEvictions: 1 });
  const resumed = await read(BIG, first.cursor);
  expect(resumed.rows.map(row => row.id)).toEqual(['b-agent-2', 'b-agent-3']);
  expect(resumed.watermark! >= first.watermark!).toBe(true);
  expect(currentStateStats().currentBytes).toBeLessThanOrEqual(budget);
  expect(currentStateStats().primaryProjects).toBe(1);
});

test('an active overflow refresh cannot be evicted; another project gets a canonical fresh read', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 2); await agentsIn(OTHER, 2); await drain(SMALL);
  let release!: () => void, entered!: () => void;
  const gate = new Promise<void>(resolve => { release = resolve; });
  const started = new Promise<void>(resolve => { entered = resolve; });
  configureCurrentState({ currentBytes: 64 * 1024, refresh: async previous => {
    if (currentProjectId() === BIG) { entered(); await gate; }
    return readCurrentStateRefresh(previous);
  } });
  const waiting = read(BIG); await started;
  try {
    const other = await drain(OTHER); expect(other.answer.complete).toBe(true);
    expect(currentStateStats()).toMatchObject({ primaryProjects: 1, overflowProjects: 1, currentBypass: 1, oneShots: 1 });
  } finally { release(); }
  expect((await waiting).complete).toBe(true);
  expect(currentStateStats().currentBytes).toBe(0); // base fits, actual rows exceed this synthetic budget
});

test('zero overflow budget serves independent request-fresh canonical inputs', async () => {
  await agentsIn(SMALL, 1); await agentsIn(OTHER, 2); await drain(SMALL);
  configureCurrentState({ currentBytes: 0 });
  const [a, b] = await Promise.all([read(OTHER), read(OTHER)]);
  expect(a.complete && b.complete).toBe(true);
  expect(currentStateStats()).toMatchObject({ oneShots: 2, currentBypass: 2 });
  await read(OTHER); expect(currentStateStats().oneShots).toBe(3);
});

test('overflow payload growth releases its charge; the active cursor recovers without losing rows', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 2); await drain(SMALL);
  const first = await drain(BIG), budget = currentStateStats().currentBytes;
  configureCurrentState({ currentBytes: budget });
  await inProject(BIG, () => updateCanonicalStatus('b-agent-0', { 'agent.focus': { text: 'x'.repeat(20_000), updatedAt: 3 } }));
  const grown = await read(BIG, first.answer.cursor);
  expect(grown.rows.find(row => row.id === 'b-agent-0')).toMatchObject({ focus: { text: 'x'.repeat(20_000) } });
  expect(currentStateStats()).toMatchObject({ currentBytes: 0, overflowProjects: 0, currentOversized: 1, primaryProjects: 1 });
  configureCurrentState({ currentBytes: 0 });
  const recovered = await read(BIG, first.answer.cursor);
  expect(recovered.rows).toEqual(grown.rows);
  expect(recovered.watermark! >= first.answer.watermark!).toBe(true);
});

test('overflow read error releases the failed cache and the next request recovers from the held cursor', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 2); await drain(SMALL);
  const first = await drain(BIG);
  configureCurrentState({ refresh: async () => { throw new Error('injected read failure'); } });
  await expect(read(BIG, first.answer.cursor)).rejects.toThrow('injected read failure');
  expect(currentStateStats().currentBytes).toBe(0);
  configureCurrentState({ refresh: readCurrentStateRefresh });
  await inProject(BIG, () => updateCanonicalStatus('b-agent-0', { 'agent.focus': { text: 'after reconnect', updatedAt: 4 } }));
  const recovered = await read(BIG, first.answer.cursor);
  expect(recovered.rows.find(row => row.id === 'b-agent-0')).toMatchObject({ focus: { text: 'after reconnect' } });
  expect(recovered.watermark! >= first.answer.watermark!).toBe(true);
});

test('linger releases overflow bytes and reconnect uses a free primary slot before overflow capacity', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 2);
  const small = await drain(SMALL);
  const first = await drain(BIG);
  // Keep both entries through setup: a slow BIG read must not consume SMALL's short linger.
  // Only start the 40 ms primary linger after the overflow entry is ready.
  configureCurrentState({ lingerMs: 40 });
  await read(SMALL, small.answer.cursor);
  configureCurrentState({ lingerMs: 60_000 });
  expect(currentStateStats()).toMatchObject({ primaryProjects: 1, overflowProjects: 1 });
  // Poll rather than sleep a fixed margin past the linger: under load the linger timer can fire late.
  await vi.waitFor(() => expect(currentStateStats()).toMatchObject({ primaryProjects: 0, overflowProjects: 1 }), { timeout: 5_000, interval: 10 });
  await read(BIG, first.answer.cursor);
  expect(currentStateStats()).toMatchObject({ primaryProjects: 1, overflowProjects: 0, currentBytes: 0, attaches: 2 });
  // Now exercise ordinary overflow linger itself, without waiting the production 30s.
  configureCurrentState({ maxProjects: 0, lingerMs: 20 });
  await drain(OTHER);
  expect(currentStateStats().overflowProjects).toBe(1);
  await vi.waitFor(() => expect(currentStateStats()).toMatchObject({ overflowProjects: 0, currentBytes: 0 }), { timeout: 5_000, interval: 10 });
});


test('one individually oversized callback does not evict an unrelated idle overflow project', async () => {
  await agentsIn(SMALL, 1); await agentsIn(BIG, 2); await agentsIn(OTHER, 2); await drain(SMALL);
  await drain(BIG); const other = await drain(OTHER);
  const budget = currentStateStats().currentBytes;
  configureCurrentState({ currentBytes: budget });
  await inProject(BIG, () => updateCanonicalStatus('b-agent-0',{ 'agent.focus': { text: 'x'.repeat(100_000), updatedAt: 5 } }));
  await read(BIG);
  expect(currentStateStats()).toMatchObject({ primaryProjects: 1, overflowProjects: 1, currentEvictions: 0, currentOversized: 1 });
  expect(currentStateStats().currentBytes).toBeGreaterThan(0);
  expect(currentStateStats().currentBytes).toBeLessThanOrEqual(budget);
  const attaches = currentStateStats().attaches;
  expect(await read(OTHER, other.answer.cursor)).toMatchObject({ complete: true, rows: [] });
  expect(currentStateStats().attaches).toBe(attaches);
});
